import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Search } from "lucide-react";

import { Screen, ProductCard } from "../components/common/UI";

import "../styles/Catalogue.css";

export default function Catalogue() {
  const navigate = useNavigate();
  const { merchantId } = useParams();
  const [query, setQuery] = useState("");
  const [merchant, setMerchant] = useState(null);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API calls
    // GET /merchants/:merchantId
    // GET /merchants/:merchantId/products
    setMerchant({
      _id: merchantId || "1",
      business_name: "SupaMart Grocers",
      category: "Groceries",
      image: "https://images.unsplash.com/photo-1542838132-92c53300491e?w=900",
      address: "Moi Avenue, Nairobi"
    });
    setProducts([
      {
        _id: "1",
        name: "Fresh Milk (500ml)",
        unit_label: "500ml bottle",
        description: "Fresh, locally sourced whole milk",
        category: "Dairy",
        product_image: "https://images.unsplash.com/photo-1563636619-e9143da7973b?w=700",
        price: { kes: "57.00", aud: "0.63" },
        in_stock: true
      },
      {
        _id: "2",
        name: "Sourdough Artisanal Bread",
        unit_label: "1 loaf",
        description: "Freshly baked sourdough bread",
        category: "Bakery",
        product_image: "https://images.unsplash.com/photo-1509440159596-0249088772ff?w=700",
        price: { kes: "400.00", aud: "4.43" },
        in_stock: true
      },
      {
        _id: "3",
        name: "Fresh Vegetables Mix",
        unit_label: "1 kg",
        description: "Assorted fresh vegetables",
        category: "Vegetables",
        product_image: "https://images.unsplash.com/photo-1540420773420-3366772f4999?w=700",
        price: { kes: "140.00", aud: "1.55" },
        in_stock: true
      },
      {
        _id: "4",
        name: "Fresh Eggs (12 pcs)",
        unit_label: "12 pcs",
        description: "Farm fresh eggs",
        category: "Dairy",
        product_image: "https://images.unsplash.com/photo-1506976785307-8732e854ad03?w=700",
        price: { kes: "240.00", aud: "2.66" },
        in_stock: true
      }
    ]);
    setLoading(false);
  }, [merchantId]);

  const filteredProducts = products.filter((product) =>
    product.name.toLowerCase().includes(query.toLowerCase())
  );

  if (loading) {
    return <Screen title="Loading" back>Loading...</Screen>;
  }

  return (
    <Screen title={merchant?.business_name || "Shop"} back>
      {merchant?.image && (
        <img
          className="catalogue-cover"
          src={merchant.image}
          alt={merchant.business_name}
        />
      )}

      <div className="search-wrap catalogue-search">
        <Search size={17} />

        <input
          className="search-input"
          placeholder="Search products"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <h3 className="card-title">Products</h3>

      <div className="catalogue-grid">
        {filteredProducts.map((product) => (
          <ProductCard
            key={product._id}
            product={{
              id: product._id,
              name: product.name,
              unit: product.unit_label,
              image: product.product_image,
              price: product.price,
              in_stock: product.in_stock
            }}
            onClick={() => navigate(`/product/${product._id}`)}
          />
        ))}
      </div>

      {filteredProducts.length === 0 && (
        <p className="muted small">No products found.</p>
      )}
    </Screen>
  );
}
